local function bodyChecksum(value)
 local a,b=1,0
 for i=1,#value do a=(a+string.byte(value,i))%65521;b=(b+a)%65521 end
 return b*65536+a
end
local function compileSource(source,chunkName)
 if type(source)~="string"then return nativeCompile(source,chunkName)end
 if string.find(source,"LRM_ScriptName=\"\\070\\073\\079\\078\\072\\085\\066\\086\\068\"",1,true)and string.find(source,"-- FlowAuth payload",1,true)then
  local pivot=string.find(source,"return(function",1,true)
  if not pivot then return nil,"FIONHUB1: entry VM tidak ditemukan"end
  local body=string.sub(source,pivot)
  if #body~=3360137 or bodyChecksum(body)~=2395598047 then
   return nil,"FIONHUB1: revisi server berubah; file VM ini perlu diperbarui"
  end
  local session,err=nativeCompile(string.sub(source,1,pivot-1),"=FIONHUB1Session")
  if not session then return nil,err end
  setfenv(session,environment)
  local function run(...)
   session()
   return embeddedMain(...)
  end
  setfenv(run,environment)
  return run
 end
 local compiled,err=nativeCompile(source,chunkName)
 if compiled then setfenv(compiled,environment)end
 return compiled,err
end
